class Solution {
public:
    string removeDuplicates(string s, int k) {
        vector<pair<char, int>> st;
        for (int i = 0; i < (int)s.size(); i++) {
            if (!st.empty() && st.back().first == s[i]) {
                if (++st.back().second == k) st.pop_back();
            } else {
                st.push_back({s[i], 1});
            }
        }
        string res;
        for (auto& [c, n] : st) res += string(n, c);
        return res;
    }
};
